   667  /* Creates an empty PFX structure for the PKCS12 structure.
   668   */
   669  static int create_empty_pfx(ASN1_TYPE pkcs12)
   670  {
   671          uint8_t three = 3;
   672          int result;
   673          ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   674
   675          /* Use version 3
   676           */
   677          result = asn1_write_value(pkcs12, "version", &three, 1);
   678          if (result != ASN1_SUCCESS) {
   679                  gnutls_assert();
   680                  result = _gnutls_asn2err(result);
   681                  goto cleanup;
   682          }
   683
   684          /* Write the content type of the data
   685           */
   686          result =
   687              asn1_write_value(pkcs12, "authSafe.contentType", DATA_OID, 1);
   688          if (result != ASN1_SUCCESS) {
   689                  gnutls_assert();
   690                  result = _gnutls_asn2err(result);
   691                  goto cleanup;
   692          }
   693
   694          /* Check if the authenticatedSafe content is empty, and encode a
   695           * null one in that case.
   696           */
   697
   698          if ((result = asn1_create_element
   699               (_gnutls_get_pkix(), "PKIX1.pkcs-12-AuthenticatedSafe",
   700                &c2)) != ASN1_SUCCESS) {
   701                  gnutls_assert();
   702                  result = _gnutls_asn2err(result);
   703                  goto cleanup;
   704          }
   705
   706          result =
   707              _gnutls_x509_der_encode_and_copy(c2, "", pkcs12,
   708                                               "authSafe.content", 1);
   709          if (result < 0) {
   710                  gnutls_assert();
   711                  goto cleanup;
   712          }
   713          asn1_delete_structure(&c2);
   714
   715          return 0;
   716
   717        cleanup:
   718          asn1_delete_structure(&c2);
   719          return result;
   720
   721  }
