   723  /**
   724   * gnutls_pkcs12_set_bag:
   725   * @pkcs12: should contain a gnutls_pkcs12_t type
   726   * @bag: An initialized bag
   727   *
   728   * This function will insert a Bag into the PKCS12 structure.
   729   *
   730   * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   731   *   negative error value.
   732   **/
   733  int gnutls_pkcs12_set_bag(gnutls_pkcs12_t pkcs12, gnutls_pkcs12_bag_t bag)
   734  {
   735          ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   736          ASN1_TYPE safe_cont = ASN1_TYPE_EMPTY;
   737          int result;
   738          int enc = 0, dum = 1;
   739          char null;
   740
   741          if (pkcs12 == NULL) {
   742                  gnutls_assert();
   743                  return GNUTLS_E_INVALID_REQUEST;
   744          }
   745
   746          /* Step 1. Check if the pkcs12 structure is empty. In that
   747           * case generate an empty PFX.
   748           */
   749          result =
   750              asn1_read_value(pkcs12->pkcs12, "authSafe.content", &null,
   751                              &dum);
   752          if (result == ASN1_VALUE_NOT_FOUND) {
   753                  result = create_empty_pfx(pkcs12->pkcs12);
   754                  if (result < 0) {
   755                          gnutls_assert();
   756                          return result;
   757                  }
   758          }
   759
   760          /* Step 2. decode the authenticatedSafe.
   761           */
   762          result = _decode_pkcs12_auth_safe(pkcs12->pkcs12, &c2, NULL);
   763          if (result < 0) {
   764                  gnutls_assert();
   765                  return result;
   766          }
   767
   768          /* Step 3. Encode the bag elements into a SafeContents
   769           * structure.
   770           */
   771          result = _pkcs12_encode_safe_contents(bag, &safe_cont, &enc);
   772          if (result < 0) {
   773                  gnutls_assert();
   774                  return result;
   775          }
   776
   777          /* Step 4. Insert the encoded SafeContents into the AuthenticatedSafe
   778           * structure.
   779           */
   780          result = asn1_write_value(c2, "", "NEW", 1);
